import React, { useEffect, useState } from "react";

function Subscriptions() {
  const [channels, setChannels] = useState([]);
  const [articles, setArticles] = useState({});
  const [polls, setPolls] = useState({});
  const token = localStorage.getItem("token");

  useEffect(() => {
    fetchChannels();
  }, []);

  const fetchChannels = async () => {
    try {
      const res = await fetch("http://127.0.0.1:8000/api/channels/", {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (!res.ok) throw new Error("Не вдалося завантажити канали");
      const data = await res.json();
      setChannels(data);

      // для кожного каналу завантажуємо статті і опитування
      data.forEach(async (channel) => {
        fetchChannelArticles(channel.id);
        fetchChannelPolls(channel.id);
      });

    } catch (err) {
      console.error(err);
    }
  };

  const fetchChannelArticles = async (channelId) => {
    try {
      const res = await fetch(`http://127.0.0.1:8000/api/channels/${channelId}/articles/`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (!res.ok) throw new Error("Не вдалося завантажити статті");
      const data = await res.json();
      setArticles(prev => ({ ...prev, [channelId]: data }));
    } catch (err) {
      console.error(err);
    }
  };

  const fetchChannelPolls = async (channelId) => {
    try {
      const res = await fetch(`http://127.0.0.1:8000/api/channels/${channelId}/polls/`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (!res.ok) throw new Error("Не вдалося завантажити опитування");
      const data = await res.json();
      setPolls(prev => ({ ...prev, [channelId]: data }));
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div>
      {channels.map((channel) => (
        <div key={channel.id}>
          <h2>{channel.name}</h2>
          <h3>Статті</h3>
          {articles[channel.id]?.map((a) => (
            <div key={a.id}>{a.title}</div>
          ))}
          <h3>Опитування</h3>
          {polls[channel.id]?.map((p) => (
            <div key={p.id}>{p.question}</div>
          ))}
        </div>
      ))}
    </div>
  );
}

export default Subscriptions;
